$activeFrom=preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',(string)($profile['active_from']??''))?(string)$profile['active_from']:'';$activeTo=preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',(string)($profile['active_to']??''))?(string)$profile['active_to']:'';
