<section class="card" style="margin-top:18px"><div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap"><h2 style="margin:0">📝 Последние посты</h2><?php if($latestPosts):?><span class="muted">Показано <?=count($latestPosts)?> последних</span><?php endif;?></div><?php if(!$latestPosts):?><p class="muted">Пользователь пока не создал постов.</p><?php else:?><div style="display:grid;gap:12px;margin-top:14px"><?php foreach($latestPosts as $post):?><a href="thread.php?id=<?= (int)($post['id']??0) ?>" class="card" style="margin:0;text-decoration:none;border-left:3px solid <?=e($accent)?>"><div style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start"><strong><?=e((string)($post['title']??'Без названия'))?></strong><span class="muted" style="font-size:12px;white-space:nowrap"><?=e((string)($post['created_at']??''))?></span></div><p class="muted" style="margin:7px 0 0"><?=e(mb_strimwidth((string)($post['content']??''),0,180,'…','UTF-8'))?></p></a><?php endforeach;?></div><?php endif;?></section>
