<script>
function copyProfileLink(button,url){
  const done=()=>{const old=button.textContent;button.textContent='✅ Ссылка скопирована';setTimeout(()=>button.textContent=old,1800);};
  const fallback=()=>{const value=prompt('Скопируйте ссылку',url);if(value!==null)done();};
  if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(url).then(done).catch(fallback);}else fallback();
}
setTimeout(()=>window.location.reload(),15000);
</script>
